#!/usr/bin/env node
// Builds /DRIVE/Runbook/runbook.html from RUNBOOK.md (hand-written) + FACTS.md (generated by runbook-facts.mjs).
// Fails if any line looks like a secret. Run: node /Oskar/ops/runbook-build.mjs
import { readFileSync, writeFileSync, existsSync, statSync } from 'node:fs'
import { join, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'
import { inline, block, sections } from './md-page.mjs'

const here = dirname(fileURLToPath(import.meta.url))
const DIR = '/DRIVE/Runbook'
const md = readFileSync(join(DIR, 'RUNBOOK.md'), 'utf8')
const facts = existsSync(join(DIR, 'FACTS.md')) ? readFileSync(join(DIR, 'FACTS.md'), 'utf8') : '# Fakten\n\n(FACTS.md fehlt — `node /Oskar/ops/runbook-facts.mjs` ausführen)'
const factsAge = existsSync(join(DIR, 'FACTS.md')) ? Math.round((Date.now() - statSync(join(DIR, 'FACTS.md')).mtimeMs) / 864e5) : 999

/* secret lint */
const SECRET = [/sk-ant-[A-Za-z0-9_-]{8,}/, /AIza[0-9A-Za-z_-]{20,}/, /(passwor[dt]|secret|token)\s*[:=]\s*\S{6,}/i, /-----BEGIN [A-Z ]*PRIVATE KEY/]
for (const [name, text] of [['RUNBOOK.md', md], ['FACTS.md', facts]])
  text.split('\n').forEach((l, n) => { for (const re of SECRET) if (re.test(l) && !/Tresor|\[TODO|nur Namen|Keys in/.test(l)) { console.error(`SECRET-LINT: ${name}:${n + 1} sieht aus wie ein Geheimnis — Build abgebrochen`); process.exit(2) } })

/* merge: hand chapters; chapters 5, 6, 7, 11 get the generated content appended */
const hand = sections(md), gen = sections(facts)
const genByNo = Object.fromEntries(gen.filter(s => s.title).map(s => [s.title.match(/^(\d+)\./)?.[1], s]))
const title = (md.match(/^# (.*)$/m) || [, 'Runbook'])[1]
const intro = hand[0].lines.filter(l => !/^# /.test(l))
const chapters = hand.slice(1).map(s => {
  const no = s.title.match(/^(\d+)\./)?.[1]
  const own = s.lines
  const extra = genByNo[no] ? genByNo[no].lines : []
  return { no, title: s.title, html: block(own) + (extra.length ? `<div class="generated"><div class="gen-tag">automatisch erzeugt · FACTS.md</div>${block(extra)}</div>` : '') }
})
const css = readFileSync(join(here, '../docs/backlog.css'), 'utf8') + `
.chap a,.lede-md a{color:var(--red);text-decoration:underline;text-underline-offset:3px;text-decoration-thickness:1px}
.chap a:hover,.lede-md a:hover{text-decoration-thickness:2px}
.chap a code,.lede-md a code{color:var(--red)}
.flag.todo{border-color:#EB0000;color:#EB0000;background:color-mix(in srgb,#EB0000 8%,transparent)}
.chap{padding:64px 0 24px;border-bottom:1px solid var(--line)}
.chap h2{font-family:var(--hn);font-weight:900;font-size:clamp(32px,3.6vw,56px);letter-spacing:-.03em;line-height:1;margin:0 0 28px}
.chap h2 small{display:block;font-family:var(--grot);font-weight:500;font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:var(--red);margin-bottom:12px}
.chap h4{font-family:var(--hn);font-weight:700;font-size:22px;letter-spacing:-.02em;margin:36px 0 12px}
.chap h5{font-family:var(--grot);font-weight:600;font-size:12px;letter-spacing:.12em;text-transform:uppercase;color:var(--grau);margin:24px 0 8px}
.chap p,.chap li{font-size:15.5px;line-height:1.55;max-width:100ch}
.chap ul,.chap ol{padding-left:1.3em;margin:0 0 12px}
.chap li{margin:0 0 6px}
.chap table{font-size:13.5px;margin:8px 0 20px}
.chap td,.chap th{padding:9px 14px 9px 0}
.chap pre{background:var(--pill);padding:12px 14px;font-size:12.5px;line-height:1.5;overflow:auto;border-radius:2px;margin:6px 0 14px;white-space:pre}
.chap code{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:.88em;background:var(--pill);padding:1px 5px;border-radius:2px}
.chap pre code{background:none;padding:0}
.generated{margin-top:28px;padding:18px 20px;border:1px solid var(--line);border-left:3px solid var(--red);background:color-mix(in srgb,var(--panel) 60%,transparent)}
.gen-tag{font-size:10.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--red);font-weight:600;margin-bottom:10px}
.stale{background:var(--red);color:#fff;padding:10px 16px;font-size:13px;letter-spacing:.06em;text-transform:uppercase;font-weight:600}
.side a .n{min-width:28px}
.search{width:100%;font:inherit;font-size:14px;padding:8px 10px;border:1px solid var(--line);background:transparent;color:var(--ink);margin-bottom:18px;outline:none}
.search:focus{border-color:var(--red)}
mark{background:var(--red);color:#fff;padding:0 2px}
@media print{.top,.side,.prog,.tools,.search{display:none!important}.wrap{display:block;padding:0}.main{padding:0}.chap{break-before:page;border:0;padding-top:0}.hero{padding:0 0 24px;break-after:page}body{background:#fff;color:#000}.generated{break-inside:avoid}a{color:inherit;text-decoration:none}}
`
const nav = chapters.map(c => `<a href="#k${c.no}"><span class="n">${c.no}</span><span>${inline(c.title.replace(/^\d+\.\s*/, ''))}</span></a>`).join('')
const html = `<!doctype html>
<html lang="de" data-theme="light">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>Runbook Mini5Server</title>
<meta name="description" content="Übergabe-Runbook für den Praxis-Server Mini5Server — generiert aus /DRIVE/Runbook/RUNBOOK.md und FACTS.md">
<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Schibsted+Grotesk:wght@400;500;600;700&display=swap">
<style>${css}</style></head>
<body>
<div class="prog" id="prog"></div>
${factsAge > 14 ? `<div class="stale">Achtung: die automatischen Fakten sind ${factsAge} Tage alt — <code>node /Oskar/ops/runbook-facts.mjs</code> ausführen</div>` : ''}
<header class="top">
  <div class="brand"><span class="sq"></span>Runbook <small>Mini5Server · Praxis Oppliger</small></div>
  <nav class="topnav">${chapters.slice(0, 6).map(c => `<a href="#k${c.no}">${c.no}</a>`).join('')}<a href="#k10">Domains</a><a href="#k11">Änderungen</a></nav>
  <div class="tools"><button class="btn" onclick="window.print()">Drucken</button><button class="btn" id="theme">Dark</button></div>
</header>
<div class="wrap">
  <aside class="side"><input class="search" id="q" placeholder="Suchen … (⌘F geht auch)"><h6>Kapitel</h6><div id="sidenav">${nav}</div></aside>
  <main class="main">
    <div class="hero">
      <div class="eyebrow rv">Takeover-Runbook · Fakten vom ${facts.match(/Erzeugt (\S+)/)?.[1]?.slice(0, 10) || '—'}</div>
      <h1 class="rv">${inline(title.replace(/ — .*/, ''))}<span class="dot">.</span></h1>
      <div class="lede-md rv">${block(intro)}</div>
    </div>
    ${chapters.map(c => `<section class="chap" id="k${c.no}"><h2><small>Kapitel ${c.no}</small>${inline(c.title.replace(/^\d+\.\s*/, ''))}</h2>${c.html}</section>`).join('')}
    <footer><span>Runbook Mini5Server · /DRIVE/Runbook</span><span>generiert ${new Date().toISOString().slice(0, 16).replace('T', ' ')}</span><span>Praxis Oppliger</span></footer>
  </main>
</div>
<script>
const root=document.documentElement,tb=document.getElementById('theme');function applyTheme(t){root.dataset.theme=t;tb.textContent=t==='dark'?'Light':'Dark';try{localStorage.setItem('runbook-theme',t)}catch(e){}}
try{const t=localStorage.getItem('runbook-theme');if(t)applyTheme(t)}catch(e){} tb.addEventListener('click',()=>applyTheme(root.dataset.theme==='dark'?'light':'dark'));
const io=new IntersectionObserver(es=>es.forEach(x=>{if(x.isIntersecting){x.target.classList.add('in');io.unobserve(x.target)}}),{rootMargin:'0px 0px -8% 0px'});document.querySelectorAll('.rv').forEach(el=>io.observe(el));
const so=new IntersectionObserver(es=>{es.forEach(x=>{if(x.isIntersecting){document.querySelectorAll('#sidenav a').forEach(a=>a.classList.toggle('on',a.getAttribute('href')==='#'+x.target.id))}})},{rootMargin:'-20% 0px -70% 0px'});document.querySelectorAll('.chap').forEach(s=>so.observe(s));
addEventListener('scroll',()=>{const h=document.documentElement;document.getElementById('prog').style.width=(h.scrollTop/(h.scrollHeight-h.clientHeight)*100)+'%'},{passive:true});
const q=document.getElementById('q');q.addEventListener('input',()=>{const v=q.value.trim().toLowerCase();document.querySelectorAll('.chap').forEach(c=>{c.style.display=!v||c.textContent.toLowerCase().includes(v)?'':'none'})});
</script>
</body></html>`
writeFileSync(join(DIR, 'runbook.html'), html)
console.log(`runbook.html: ${chapters.length} Kapitel, ${(md.match(/\[TODO/g) || []).length} TODOs, Fakten ${factsAge} Tage alt`)
